import fs from 'node:fs';
import path from 'node:path';
import { execFileSync, spawnSync } from 'node:child_process';
import { randomUUID } from 'node:crypto';
import {
  canonical, DeliverError, internalDirectory, readRun, remoteProviderAttemptIdentity,
  remoteProviderAttemptObservation, sha256,
  validateRemotePublicationRecord, validateTaskPacket,
} from './state.mjs';
import {
  applyIntegrationCorrectionJournal,
  assertCurrentBinding,
  buildIntegrationCorrectionPublication,
  integrationCorrectionJournalConflicts,
  readIntegrationCorrectionJournal,
  removeIntegrationCorrectionJournal,
  validateIntegrationCorrectionJournal,
  writeIntegrationCorrectionJournal,
} from './current-pm.mjs';
import { inspectProjectState, readPlanPolicy } from './project-state.mjs';
import { parseReviewReceipt } from './review.mjs';
import { parseVerificationResults, renderVerificationArtifacts } from './reporting.mjs';
import { parseStory, readStory, replaceStoryExecution } from './story.mjs';
import { environmentHandle } from './gates.mjs';
import { captureGitAnchor, snapshot } from './scope.mjs';
import { createGitHubRemoteAdapter } from './remote.mjs';

const OID = /^[0-9a-f]{40}(?:[0-9a-f]{24})?$/;
const HASH = /^[0-9a-f]{64}$/;
const RUN_ID = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;
const ACTOR_ID = /^[A-Za-z0-9][A-Za-z0-9._@-]{0,127}$/;
const MAX_RECORD_BYTES = 8 * 1024 * 1024;
const NO_MUTATION = Symbol('no-mutation');
const PROCESS_INSTANCE = randomUUID();
const ACTIVE_PROVIDER_INVOCATIONS = new Set();
const ENDED_PROVIDER_INVOCATIONS = new Set();
const fail = (message, code = 66) => { throw new DeliverError(message, code); };
const json = (value) => `${JSON.stringify(value, null, 2)}\n`;
const now = () => new Date().toISOString();
const stamp = () => now().replace('T', ' ').replace('Z', '').slice(0, 16);
const covers = (scope, rel) => scope === rel || rel.startsWith(`${scope}/`);

function git(root, args, { buffer = false, env = undefined } = {}) {
  try {
    return execFileSync('git', ['-C', root, ...args], {
      encoding: buffer ? undefined : 'utf8', stdio: ['ignore', 'pipe', 'pipe'], timeout: 30000,
      windowsHide: true, ...(env ? { env: { ...process.env, ...env } } : {}),
    });
  } catch (error) {
    fail(`Git cannot complete local integration: ${String(error.stderr || error.message).trim()}`);
  }
}

function rootPath(root) {
  try {
    const real = fs.realpathSync.native(root);
    const stat = fs.lstatSync(real);
    if (!stat.isDirectory() || stat.isSymbolicLink()) fail('integration root must be a real directory');
    return real;
  } catch (error) {
    if (error instanceof DeliverError) throw error;
    fail(`cannot access integration root: ${error.message}`);
  }
}

function commonRepository(root) {
  const value = String(git(root, ['rev-parse', '--git-common-dir'])).trim();
  return fs.realpathSync.native(path.resolve(root, value));
}

function branch(root) {
  const value = String(git(root, ['symbolic-ref', '--short', 'HEAD'])).trim();
  if (!value) fail('integration checkout must use a named branch');
  return value;
}

function head(root) { return String(git(root, ['rev-parse', '--verify', 'HEAD'])).trim(); }
function tree(root, commit = 'HEAD') { return String(git(root, ['rev-parse', `${commit}^{tree}`])).trim(); }

function statusPaths(root) {
  const records = String(git(root, ['status', '--porcelain=v1', '-z', '--untracked-files=all'])).split('\0').filter(Boolean);
  const paths = [];
  for (let index = 0; index < records.length; index++) {
    const item = records[index];
    if (item.length < 4) continue;
    const status = item.slice(0, 2);
    paths.push(item.slice(3));
    if ((status[0] === 'R' || status[0] === 'C') && records[index + 1]) paths.push(records[++index]);
  }
  return paths.filter((rel) => rel !== '.deliver' && !rel.startsWith('.deliver/'));
}

function assertClean(root) {
  const dirty = statusPaths(root);
  if (dirty.length) fail(`integration checkout has uncommitted project paths: ${dirty.sort().join(', ')}`);
  const indexTree = String(git(root, ['write-tree'])).trim();
  if (indexTree !== tree(root)) fail('integration checkout index differs from HEAD');
}

function assertOrdinaryIndex(root) {
  const rows = git(root, ['ls-files', '-v', '-z'], { buffer: true }).toString('utf8').split('\0').filter(Boolean);
  const hidden = rows.filter((row) => row[0] !== 'H').map((row) => row.slice(2));
  if (hidden.length) fail(`integration checkout has unsupported index flags: ${hidden.sort().join(', ')}`);
}

function protectedShape(anchor, root = true) {
  return {
    metadata_version: anchor.metadata_version,
    ...(root ? { ref: anchor.ref } : {}),
    protected_hash: anchor.protected_hash,
    submodules: Object.fromEntries(Object.entries(anchor.submodules || {})
      .map(([rel, nested]) => [rel, protectedShape(nested, false)])),
  };
}

const protectedIgnored = (rel) => /(^|\/)(?:AGENTS|CLAUDE)\.md$/.test(rel)
  || /(^|\/)\.(?:agents|codex)(?:\/|$)/.test(rel)
  || rel.endsWith('.sdd') || /(^|\/)\.specdd(?:\/|$)/.test(rel)
  || /(^|\/)(?:config|configs|contract|contracts)(?:[./]|$)/.test(rel);

function remoteEvidenceRoot(record) {
  const evidence = record.remote?.integration_evidence;
  if (!evidence || evidence.status === 'prepared') fail('remote integration evidence checkout is not prepared');
  const root = rootPath(evidence.root);
  if (commonRepository(root) !== record.destination.common_repository || branch(root) !== evidence.branch
    || head(root) !== evidence.commit) fail('remote evidence checkout no longer identifies fetched M');
  assertClean(root); assertOrdinaryIndex(root);
  verifyCheckoutProof(root, evidence.commit, evidence.checkout_proof, evidence.anchor);
  return root;
}

export function prepareRemoteIntegrationEvidence(recordArg, {
  expectedRecordHash, evidenceRoot,
} = {}, cwd = process.cwd()) {
  return withRecord(recordArg, expectedRecordHash, (record) => {
    const proof = record.remote?.source?.proof;
    if (!proof) fail('proved remote source lineage is required');
    const root = rootPath(evidenceRoot);
    const existing = record.remote.integration_evidence;
    if (existing) {
      if (existing.root !== root || existing.branch !== proof.evidence_branch
        || existing.commit !== proof.verified_integration_commit) fail('remote evidence resume differs from retained checkout');
      remoteEvidenceRoot(record);
      return { [NO_MUTATION]: true, value: remoteResult('remote-evidence-prepare', 'REMOTE_EVIDENCE_PREPARED', {
        root, branch: existing.branch, commit: existing.commit, snapshot_hash: existing.snapshot_hash }) };
    }
    if (commonRepository(root) !== record.destination.common_repository || branch(root) !== proof.evidence_branch
      || head(root) !== proof.verified_integration_commit) fail('remote evidence checkout does not match its allocated branch and M');
    assertClean(root); assertOrdinaryIndex(root);
    const attachments = String(git(root, ['worktree', 'list', '--porcelain'])).split(/\r?\n/)
      .filter((line) => line === `branch refs/heads/${proof.evidence_branch}`).length;
    if (attachments !== 1) fail('remote evidence branch must have one exact worktree attachment');
    const anchor = captureGitAnchor(root);
    const checkoutProof = buildCheckoutProof(root, proof.verified_integration_commit, anchor);
    verifyCheckoutProof(root, proof.verified_integration_commit, checkoutProof, anchor);
    const manifest = boundManifest(root, proof.verified_integration_commit, record.source.packet,
      record.source.story_path, record.integration.manifest.bindings);
    record.remote.integration_evidence = {
      version: 'remote-integration-evidence-v1', status: 'ready', root, branch: proof.evidence_branch,
      commit: proof.verified_integration_commit, anchor, checkout_proof: checkoutProof, manifest,
      source_reusable: manifest.hash === record.integration.manifest.hash,
      snapshot_hash: sha256(canonical({ commit: proof.verified_integration_commit, manifest: manifest.hash,
        anchor: sha256(canonical(anchor)), checkout: sha256(canonical(checkoutProof)) })),
      gates: [], gate_history: [], review: null, review_history: [], verification: null,
      verification_history: [], finalized: false, finalization: null, prepared_at: now(),
    };
    return remoteResult('remote-evidence-prepare', 'REMOTE_EVIDENCE_PREPARED', {
      root, branch: proof.evidence_branch, commit: proof.verified_integration_commit,
      snapshot_hash: record.remote.integration_evidence.snapshot_hash,
    });
  }, cwd);
}

export function runRemoteIntegrationGate(recordArg, { expectedRecordHash, name } = {}, cwd = process.cwd()) {
  return withRecord(recordArg, expectedRecordHash, (record) => {
    const evidence = record.remote?.integration_evidence;
    assertRemoteEvidenceMutable(record);
    const root = remoteEvidenceRoot(record);
    const command = record.source.packet.commands?.[name];
    if (typeof command !== 'string') fail('remote integration gate is not declared by the source task');
    const started = now();
    const result = spawnSync(command, { cwd: root, shell: true, encoding: 'utf8', timeout: 10 * 60 * 1000,
      maxBuffer: 1024 * 1024, windowsHide: true });
    let stable = true; try { remoteEvidenceRoot(record); } catch { stable = false; }
    const logDir = internalDirectory(root, ['logs', `remote-integration-${record.id}`]);
    const log = path.join(logDir, `${name}-${randomUUID()}.log`);
    const logText = `command: ${command}\nstarted: ${started}\nexit: ${result.status}\n\n[stdout]\n${result.stdout || ''}\n[stderr]\n${result.stderr || ''}`;
    fs.writeFileSync(log, logText, { flag: 'wx', mode: 0o600 });
    const receipt = identified({ provenance: 'deliver-remote-integration-gate-v1', name, command,
      integration_commit: evidence.commit, snapshot_hash: evidence.snapshot_hash,
      status: result.status === 0 && !result.error && stable ? 'PASS' : 'FAIL', exit_code: result.status,
      signal: result.signal || null, error: result.error?.message || null, started_at: started, finished_at: now(),
      log_path: path.relative(root, log).split(path.sep).join('/'), log_hash: sha256(logText) });
    const previous = evidence.gates.find((item) => item.name === name);
    if (previous) evidence.gate_history.push(previous);
    evidence.gates = evidence.gates.filter((item) => item.name !== name); evidence.gates.push(receipt);
    evidence.finalized = false; evidence.finalization = null;
    return remoteResult('remote-evidence-gate', receipt.status === 'PASS' ? 'PASSED' : 'FAILED', { receipt });
  }, cwd);
}

export function recordRemoteIntegrationReview(recordArg, {
  expectedRecordHash, reviewer, receipt,
} = {}, cwd = process.cwd()) {
  return withRecord(recordArg, expectedRecordHash, (record) => {
    const evidence = record.remote?.integration_evidence; remoteEvidenceRoot(record);
    assertRemoteEvidenceMutable(record);
    if (!ACTOR_ID.test(reviewer || '') || reviewer === record.source.builder) fail('remote integration reviewer must differ from the builder');
    const parsed = parseReviewReceipt(receipt, { expectedSnapshot: evidence.snapshot_hash });
    const value = identified({ ...parsed, reviewer, snapshot_hash: evidence.snapshot_hash, recorded_at: now() });
    if (evidence.review) evidence.review_history.push(evidence.review); evidence.review = value;
    evidence.finalized = false; evidence.finalization = null;
    return remoteResult('remote-evidence-review', 'RECORDED', { receipt: value });
  }, cwd);
}

export function recordRemoteIntegrationVerification(recordArg, {
  expectedRecordHash, verifier, results,
} = {}, cwd = process.cwd()) {
  return withRecord(recordArg, expectedRecordHash, (record) => {
    const evidence = record.remote?.integration_evidence; remoteEvidenceRoot(record);
    assertRemoteEvidenceMutable(record);
    const reviewers = new Set([evidence.review?.reviewer, ...(evidence.review?.panel?.members || []).map((item) => item.reviewer)]);
    if (!ACTOR_ID.test(verifier || '') || verifier === record.source.builder || reviewers.has(verifier)) fail('remote integration verifier is not independent');
    const criteria = parseVerificationResults(results, record.source.packet.acceptance);
    const value = identified({ verifier, criteria, snapshot_hash: evidence.snapshot_hash, recorded_at: now() });
    if (evidence.verification) evidence.verification_history.push(evidence.verification); evidence.verification = value;
    evidence.finalized = false; evidence.finalization = null;
    return remoteResult('remote-evidence-verification', 'RECORDED', { receipt: value });
  }, cwd);
}

export function finalizeRemoteIntegrationEvidence(recordArg, { expectedRecordHash } = {}, cwd = process.cwd()) {
  return withRecord(recordArg, expectedRecordHash, (record) => {
    const evidence = record.remote?.integration_evidence; remoteEvidenceRoot(record);
    assertRemoteEvidenceMutable(record);
    for (const [name, command] of Object.entries(record.source.packet.commands)) {
      if (!evidence.gates.some((item) => item.name === name && item.command === command && item.status === 'PASS'
        && item.snapshot_hash === evidence.snapshot_hash)) fail(`fresh remote integration gate is missing or failed: ${name}`);
    }
    if (!evidence.review || evidence.review.status !== 'PASS' || evidence.review.snapshot_hash !== evidence.snapshot_hash
      || evidence.review.findings.some((item) => !item.resolved && item.severity !== 'minor')) fail('remote integration review is incomplete');
    if (!evidence.verification || evidence.verification.snapshot_hash !== evidence.snapshot_hash
      || evidence.verification.criteria.some((item) => item.status !== 'PASS')) fail('remote integration verification is incomplete');
    const finalization = identified({ version: 'remote-integration-finalization-v1', snapshot_hash: evidence.snapshot_hash,
      gates: evidence.gates.map((item) => item.identity).sort(), review: evidence.review.identity,
      verification: evidence.verification.identity, finalized_at: now() });
    evidence.finalized = true; evidence.finalization = finalization;
    return remoteResult('remote-evidence-finalize', 'REMOTE_EVIDENCE_FINALIZED', { finalization: finalization.identity });
  }, cwd);
}
export function prepareRemoteClosureCheckout(recordArg, { expectedRecordHash } = {}, cwd = process.cwd()) {
  return withRecord(recordArg, expectedRecordHash, (record) => {
    const evidence = record.remote?.integration_evidence;
    if (!evidence?.finalized || !evidence.finalization) fail('finalized remote integration evidence is required');
    if (record.remote.closure) {
      const checkout = record.remote.closure.checkout;
      return { [NO_MUTATION]: true, value: remoteResult('remote-closure-checkout-prepare', 'CLOSURE_CHECKOUT_PREPARED', {
        token: checkout.token, branch: checkout.branch, start_commit: checkout.start_commit }) };
    }
    const token = randomUUID();
    const checkout = { status: 'prepared', token, branch: `pm/${record.source.story}-closure-${token}`,
      start_commit: evidence.commit, root: null, anchor: null, checkout_proof: null, prepared_at: now(), adopted_at: null };
    record.remote.closure = { version: 'remote-closure-v1', checkout,
      artifacts: { report: { pending: null, commit: null, proof: null }, closure: { pending: null, commit: null, proof: null },
        handoff: { path: record.handoff.path, pending: null, commit: null, proof: null } },
      publication: { publish: emptyProviderSlot(), merge: emptyProviderSlot() }, proof: null };
    return remoteResult('remote-closure-checkout-prepare', 'CLOSURE_CHECKOUT_PREPARED', {
      token, branch: checkout.branch, start_commit: checkout.start_commit });
  }, cwd);
}

export function adoptRemoteClosureCheckout(recordArg, {
  expectedRecordHash, token, closureRoot,
} = {}, cwd = process.cwd()) {
  return withRecord(recordArg, expectedRecordHash, (record) => {
    const checkout = record.remote?.closure?.checkout;
    if (!checkout || checkout.token !== token || checkout.status !== 'prepared') fail('remote closure checkout token is invalid');
    const root = rootPath(closureRoot);
    if (commonRepository(root) !== record.destination.common_repository || branch(root) !== checkout.branch
      || head(root) !== checkout.start_commit) fail('remote closure checkout does not match the allocated branch and M');
    assertClean(root); assertOrdinaryIndex(root);
    const attachments = String(git(root, ['worktree', 'list', '--porcelain'])).split(/\r?\n/)
      .filter((line) => line === `branch refs/heads/${checkout.branch}`).length;
    if (attachments !== 1) fail('remote closure branch must have one exact worktree attachment');
    checkout.root = root; checkout.anchor = captureGitAnchor(root);
    checkout.checkout_proof = buildCheckoutProof(root, checkout.start_commit, checkout.anchor);
    verifyCheckoutProof(root, checkout.start_commit, checkout.checkout_proof, checkout.anchor);
    checkout.status = 'ready'; checkout.adopted_at = now();
    return remoteResult('remote-closure-checkout-adopt', 'CLOSURE_CHECKOUT_READY', { root, branch: checkout.branch, commit: checkout.start_commit });
  }, cwd);
}

function remoteClosureRoot(record, expectedHead = undefined, { clean = false } = {}) {
  const checkout = record.remote?.closure?.checkout;
  if (!checkout || checkout.status !== 'ready') fail('remote closure checkout is not ready');
  const root = rootPath(checkout.root);
  if (commonRepository(root) !== record.destination.common_repository || branch(root) !== checkout.branch
    || (expectedHead && head(root) !== expectedHead)) fail('remote closure checkout identity changed');
  if (clean) { assertClean(root); assertOrdinaryIndex(root); }
  const liveAnchor = captureGitAnchor(root);
  if (liveAnchor.protected_hash !== checkout.anchor.protected_hash
    || canonical(protectedIgnoredEntries(root)) !== canonical(checkout.checkout_proof.protected_ignored)) {
    fail('remote closure protected metadata changed');
  }
  return root;
}

function remoteArtifactsStarted(record) {
  return ['report', 'closure', 'handoff'].some((field) => {
    const slot = record.remote?.closure?.artifacts?.[field];
    return slot?.pending !== null && slot?.pending !== undefined
      || slot?.commit !== null && slot?.commit !== undefined;
  });
}

function assertRemoteEvidenceMutable(record) {
  if (remoteArtifactsStarted(record)) fail('remote integration evidence is frozen by a closure artifact');
}

function remoteEvidenceView(record, { closureCommit, destinationBranch } = {}) {
  const view = structuredClone(record);
  const evidence = record.remote.integration_evidence;
  delete view.remote;
  delete view.revision;
  delete view.created_at;
  delete view.updated_at;
  view.integration = { ...view.integration, commit: evidence.commit, tree: tree(evidence.root, evidence.commit) };
  view.manifest = structuredClone(evidence.manifest);
  view.evidence = {
    source_reusable: evidence.source_reusable,
    gates: structuredClone(evidence.gates),
    review: structuredClone(evidence.review),
    verification: structuredClone(evidence.verification),
    finalized: true,
    finalization: structuredClone(evidence.finalization),
  };
  view.closure = { ...view.closure,
    commit: closureCommit === undefined
      ? record.remote.closure?.artifacts?.closure?.commit || null
      : closureCommit };
  if (destinationBranch !== undefined) view.destination.branch = destinationBranch;
  else if (record.remote.closure?.checkout?.branch) view.destination.branch = record.remote.closure.checkout.branch;
  return view;
}

function remoteArtifactGeneration(record, field, inputs, options = {}) {
  const evidence = record.remote?.integration_evidence;
  return identified({
    version: 'remote-artifact-generation-v1',
    field,
    source_proof: structuredClone(record.remote?.source?.proof),
    finalization: structuredClone(evidence?.finalization),
    view: remoteEvidenceView(record, options),
    inputs: structuredClone(inputs),
  });
}

function generatedRemoteWrites(generation) {
  const { field, inputs, view } = generation;
  if (field === 'report') {
    const story = parseStory(inputs.story_before, view.source.story_path);
    const artifacts = renderVerificationArtifacts(view, story, view.evidence.review, view.evidence.verification);
    return [
      { path: `docs/verification/${view.source.story}.md`, after: artifacts.report },
      { path: `docs/checklists/verification-${view.source.story}.md`, after: artifacts.checklist },
    ];
  }
  if (field === 'closure') {
    const story = parseStory(inputs.story_before, view.source.story_path);
    const closed = replaceStoryExecution(story, { status: 'merged', updated: inputs.closed_at }, {
      note: `${inputs.closed_at} remotely integrated at ${view.integration.commit}`,
    });
    if (closed.executionHash !== inputs.execution_hash) fail('remote closure generated execution identity changed');
    return [{ path: view.source.story_path, after: closed.after }];
  }
  if (field === 'handoff' || field === 'handoff-repair') {
    return [{ path: view.handoff.path,
      after: handoffContent(view, inputs.handoff_at, inputs.next, view.evidence.review) }];
  }
  fail('remote artifact generation field is invalid');
}

function committedArtifactImage(root, parent, rel) {
  const entry = commitEntry(root, parent, rel, { allowMissing: true });
  return { before: entry ? committedText(root, parent, rel) : null, expected_mode: entry?.mode || '100644' };
}

function materializeRemoteWrites(root, parent, drafts) {
  return drafts.map((draft) => {
    const rel = safeTrackedPath(draft.path);
    if (typeof draft.after !== 'string' || Buffer.byteLength(draft.after) > 8 * 1024 * 1024) {
      fail('remote artifact bytes are invalid');
    }
    const retained = committedArtifactImage(root, parent, rel);
    if (readArtifact(root, rel) !== retained.before) fail(`remote artifact parent image changed: ${rel}`);
    return { path: rel, before: retained.before, after: draft.after, hash: sha256(draft.after),
      expected_mode: retained.expected_mode };
  });
}

function validateRemoteGeneration(record, field, pending, root, options = {}) {
  if (!pending || pending.version !== 'remote-artifact-pending-v1' || pending.field !== field
    || pending.identity !== sha256(canonical(Object.fromEntries(Object.entries(pending)
      .filter(([key]) => key !== 'identity'))))
    || typeof pending.token !== 'string' || !pending.token
    || !OID.test(pending.parent || '') || !Array.isArray(pending.writes) || !pending.writes.length) {
    fail(`remote ${field} pending image is invalid`);
  }
  const generation = pending.generation;
  if (!generation || generation.version !== 'remote-artifact-generation-v1' || generation.field !== field
    || generation.identity !== sha256(canonical(Object.fromEntries(Object.entries(generation)
      .filter(([key]) => key !== 'identity'))))) fail(`remote ${field} generated image is invalid`);
  const expectedGeneration = remoteArtifactGeneration(record, field, generation.inputs, options);
  if (canonical(generation) !== canonical(expectedGeneration)) fail(`remote ${field} generation basis changed`);
  const expectedWrites = generatedRemoteWrites(generation).map((draft) => {
    const retained = committedArtifactImage(root, pending.parent, safeTrackedPath(draft.path));
    return { path: draft.path, before: retained.before, after: draft.after, hash: sha256(draft.after),
      expected_mode: retained.expected_mode };
  });
  if (canonical(pending.writes) !== canonical(expectedWrites)) fail(`remote ${field} pending write shape changed`);
  return pending;
}

function assertRemotePendingStatus(root, parent, writes) {
  if (head(root) !== parent) fail('remote pending parent is no longer current');
  assertOrdinaryIndex(root);
  const allowed = new Set(writes.map((write) => write.path));
  const extra = statusPaths(root).filter((rel) => !allowed.has(rel));
  if (extra.length) fail(`remote pending recovery found unrelated checkout status: ${extra.sort().join(', ')}`);
  for (const write of writes) {
    const current = readArtifact(root, write.path);
    if (current !== write.before && current !== write.after) {
      fail(`remote pending image changed: ${write.path}`);
    }
  }
}

function remotePrepareArtifact(recordArg, expectedRecordHash, field, build, cwd) {
  const updated = withRecord(recordArg, expectedRecordHash, (record) => {
    const slot = record.remote?.closure?.artifacts?.[field];
    if (!slot) fail(`remote ${field} artifact slot is unavailable`);
    if (field === 'handoff' && !record.remote.closure.artifacts.closure.commit) {
      fail('adopted remote story closure E is required before handoff preparation');
    }
    const parent = field === 'report' ? record.remote.integration_evidence.commit
      : field === 'closure' ? (record.remote.closure.artifacts.report.commit || record.remote.integration_evidence.commit)
        : record.remote.closure.artifacts.closure.commit;
    const root = remoteClosureRoot(record, parent, { clean: !slot.pending });
    if (slot.commit) fail(`remote ${field} commit is already adopted`);
    if (slot.pending) {
      validateRemoteGeneration(record, field, slot.pending, root);
      assertRemotePendingStatus(root, parent, slot.pending.writes);
      return { [NO_MUTATION]: true, value: slot.pending };
    }
    const built = build(record, root, parent);
    const generation = remoteArtifactGeneration(record, field, built.inputs);
    const writes = materializeRemoteWrites(root, parent, generatedRemoteWrites(generation));
    const pending = identified({ version: 'remote-artifact-pending-v1', field,
      token: randomUUID(), parent, generation, writes, prepared_at: now() });
    slot.pending = pending; return pending;
  }, cwd);
  applyPending(updated.record.remote.closure.checkout.root, updated.result);
  return { ...updated, result: remoteResult(`remote-${field}-prepare`, 'PREPARED', { token: updated.result.token,
    parent: updated.result.parent, paths: updated.result.writes.map((item) => item.path) }) };
}

function remoteAdoptArtifact(recordArg, { expectedRecordHash, token, commit } = {}, field, cwd) {
  return withRecord(recordArg, expectedRecordHash, (record) => {
    const slot = record.remote?.closure?.artifacts?.[field]; const pending = slot?.pending;
    if (!pending || pending.token !== token || !OID.test(commit || '')) fail(`remote ${field} adoption token or commit is invalid`);
    const root = remoteClosureRoot(record, commit, { clean: true });
    validateRemoteGeneration(record, field, pending, root);
    const parents = String(git(root, ['rev-list', '--parents', '-n', '1', commit])).trim().split(/\s+/);
    if (parents.length !== 2 || parents[1] !== pending.parent) fail(`remote ${field} must be a direct child of its prepared parent`);
